<?php
/** TEMP PS S1685 mp — DEPLOY petshop-pakartoti.php v1.1.0 (grupavimas pagal užsakymą) + šablonas v1.1; bak _s1685b, token_get_all, heartbeat, rollback. */
add_action('init', function(){
  if (!isset($_GET['ps_s1685mp'])) return; $o=array('v'=>'S1685 mp'); $f=WPMU_PLUGIN_DIR.'/petshop-pakartoti.php'; $t=WPMU_PLUGIN_DIR.'/ps-sablonai/refill-pakartoti.php'; $bd=WP_CONTENT_DIR.'/uploads/ps-backups';
  copy($f,$bd.'/petshop-pakartoti.php.bak_s1685b'); copy($t,$bd.'/refill-pakartoti.php.bak_s1685b');
  $np=base64_decode(''); $nt=base64_decode(''); if(md5($np)!=='646ffb3706c0ff6998aca204071d60eb'||md5($nt)!=='97a74a4027976c271357962ea3876c91'){ $o['STOP']='md5 payload'; echo json_encode($o); exit; }
  try { token_get_all($np, TOKEN_PARSE); token_get_all($nt, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']='ParseError: '.$e->getMessage(); echo json_encode($o); exit; }
  file_put_contents($t,$nt); file_put_contents($f,$np); if(function_exists('opcache_invalidate')){ opcache_invalidate($f,true); opcache_invalidate($t,true); } $o['md5']=array(md5_file($f),md5_file($t));
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $code=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $o['heartbeat']=$code; if($code>=500||$code===0){ copy($bd.'/petshop-pakartoti.php.bak_s1685b',$f); copy($bd.'/refill-pakartoti.php.bak_s1685b',$t); $o['ROLLBACK']='bak'; }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
